#!/usr/bin/env python3
"""Write the LC registers (sources, ecosystem, providers, v1 assessment, candidates, role signals)
from the curated lists below, with schema validation. Run from repo root:
    python3 -I docs/research/learning-curriculum/scripts/build_lc_registers.py
All content is LC-authored research data; see report.md for evidence labels and limits.
"""
import csv
import os
import re

HERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))  # role folder (outputs live here)
ACC = "2026-10-23"

def w(name, fields, rows):
    path = os.path.join(HERE, name)
    for r in rows:
        assert len(r) == len(fields), (name, r[0], len(r), len(fields))
    with open(path, "w", newline="", encoding="utf-8") as fh:
        wr = csv.writer(fh)
        wr.writerow(fields)
        wr.writerows(rows)
    return path, len(rows)

