def check_ids(rows, pat):
    for r in rows:
        assert re.match(pat, r[0]), r[0]
    ids = [r[0] for r in rows]
    assert len(ids) == len(set(ids)), "duplicate ids"

if __name__ == "__main__":
    check_ids(S, r"^LC-\d{3}$"); check_ids(E, r"^LC-E-\d{2}$"); check_ids(T, r"^TP-\d{3}$")
    check_ids(C, r"^LC-C-\d{2}$"); check_ids(R, r"^LC-R-\d{2}$")
    src_ids = {r[0] for r in S}
    for name, rows, col in [("ecosystem", E, 11), ("providers", T, 9), ("v1", V, 5), ("cand", C, 10), ("roles", R, 9)]:
        for r in rows:
            for s in filter(None, r[col].split("|")):
                assert s in src_ids, (name, r[0], s)
    for r in S:
        assert r[5] in {"peer-reviewed", "government", "standard", "dataset", "index", "industry-report", "job-posting", "grey-literature", "news", "practitioner", "legal"}, r[0]
        assert r[9] in {"current", "outdated", "poor-fit", "unverified"} or r[9].startswith("superseded-by:"), r[0]
    for r in T:
        assert r[2] in {"federal", "state", "tribal", "ngo", "academic", "private"}, r[0]
    for r in V:
        assert r[2] in {"carry", "change", "retire", "add", "needs-evidence"}, r[0]
    for r in C:
        assert r[3] in {"FC", "DC", "SC"} and r[4] in {"FC", "DC", "SC", ""}, r[0]
        assert r[7] in {"new", "emerging", "transforming", "stable", "declining"}, r[0]
        assert r[9] in {"E", "J", "S"}, r[0]
        assert all(a in {"federal", "state", "local", "tribal", "ngo", "private", "academic"} for a in r[6].split("|")), r[0]
        assert all(d in {"AI", "automation-robotics", "sensing-tech", "policy-reform", "climate", "market", "demographic", "fiscal", "other"} for d in r[8].split("|")), r[0]
    for r in R:
        assert r[4] in {"new-role", "transforming-role", "declining-role", "merging-roles", "splitting-role", "skill-shift", "entry-path-at-risk"}, r[0]
        assert r[7] in {"now", "1-3y", "3-5y", "5-10y", "10y+"}, r[0]
    for r in E:
        assert r[2] in {"index", "dataset", "research-program", "paper", "working-group", "coalition", "organization", "fund", "standard", "tool", "platform", "policy", "credential"}, r[0]
        assert all(x in {"ingest", "crosswalk", "benchmark", "partner", "funder", "adopter", "validator", "distribution", "watch"} for x in r[7].split("|")), r[0]
    out = [w("sources.csv", SF, S), w("ecosystem.csv", EF, E), w("training_providers_register.csv", TF, T),
           w("v1_assessment.csv", VF, V), w("candidate_competencies.csv", CF, C), w("role_signals.csv", RF, R)]
    for p, n in out:
        print(f"wrote {os.path.basename(p)}: {n} rows")
